=== package.json
     1	{ "name": "billing", "private": true, "scripts": { "test": "node --test" } }
=== src/invoices.js
     1	// An invoice has one total and one due date. Status: sent -> paid, or sent -> overdue -> paid.
     2	const invoices = new Map([['i1', { id: 'i1', totalCents: 10000, dueDate: '2026-02-01', status: 'sent', paidCents: 0 }]]);
     3	module.exports = { invoices };
=== src/latefees.js
     1	// A 2% late fee is added once when an invoice becomes overdue.
     2	function lateFeeCents(invoice) { return Math.round(invoice.totalCents * 0.02); }
     3	module.exports = { lateFeeCents };
=== src/payments.js
     1	const { invoices } = require('./invoices');
     2	function recordPayment(id, cents) {
     3	  const inv = invoices.get(id); inv.paidCents += cents;
     4	  if (inv.paidCents >= inv.totalCents) inv.status = 'paid';
     5	  return inv;
     6	}
     7	module.exports = { recordPayment };
=== src/reminders.js
     1	// Sends one reminder 3 days before an invoice's due date.
     2	function reminderDate(invoice) { const d = new Date(invoice.dueDate); d.setDate(d.getDate() - 3); return d.toISOString().slice(0, 10); }
     3	module.exports = { reminderDate };
=== test/billing.test.js
     1	const test = require('node:test'); const assert = require('node:assert');
     2	const { recordPayment } = require('../src/payments');
     3	const { lateFeeCents } = require('../src/latefees');
     4	test('full payment marks the invoice paid', () => assert.strictEqual(recordPayment('i1', 10000).status, 'paid'));
     5	test('late fee is 2% of the total', () => assert.strictEqual(lateFeeCents({ totalCents: 10000 }), 200));

